def minReplacementsToContain(s, t):
    n, m = len(s), len(t)
    if m > n:
        return -1
    best = m
    for i in range(n - m + 1):
        bad = 0
        for a, b in zip(s[i:i + m], t):
            if a != b:
                bad += 1
                if bad >= best:
                    break
        if bad < best:
            best = bad
            if best == 0:
                break
    return best
